@layer components {
  :where([data-control-family="page-layout"][data-slot="root"]) {
    --cui-page-layout-article-size: 40rem;
    --cui-page-layout-aside-size: 11.25rem;
    --cui-page-layout-padding-inline: calc(var(--spacing) * 5);
    --cui-page-layout-padding-block: calc(var(--spacing) * 10) calc(var(--spacing) * 24);
    --cui-page-layout-column-gap: calc(var(--spacing) * 5);
    --cui-page-layout-header-start-gap: calc(var(--spacing) * 10);
    --cui-page-layout-header-gap: calc(var(--spacing) * 8);
    --cui-page-layout-header-column-gap: calc(var(--spacing) * 4);
    --cui-page-layout-header-row-gap: calc(var(--spacing) * 2);
    --cui-page-layout-sticky-gap: 0px;

    /* Header and body both read this, so they stop at the same right edge. */
    --cui-page-layout-size: calc(var(--cui-page-layout-article-size) + var(--cui-page-layout-padding-inline) * 2);
  }

  :where([data-control-family="page-layout"][data-slot="root"][data-width="content"]) {
    --cui-page-layout-article-size: 48rem;
  }

  :where([data-control-family="page-layout"][data-slot="root"][data-width="wide"]) {
    --cui-page-layout-article-size: 80rem;
  }

  :where([data-control-family="page-layout"][data-slot="root"][data-width="full"]) {
    --cui-page-layout-size: none;
    --cui-page-layout-padding-inline: calc(var(--spacing) * 6);
  }

  :where([data-control-family="page-layout"][data-slot="header"]) {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "title" "description" "actions";
    align-items: center;
    width: 100%;
    max-width: var(--cui-page-layout-size);
    margin-inline: auto;
    column-gap: var(--cui-page-layout-header-column-gap);
    row-gap: var(--cui-page-layout-header-row-gap);
    padding-inline: var(--cui-page-layout-padding-inline);
    padding-block: var(--cui-page-layout-header-start-gap) var(--cui-page-layout-header-gap);
  }

  :where([data-control-family="page-layout"][data-slot="body"]) {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
    max-width: var(--cui-page-layout-size);
    margin-inline: auto;
    gap: var(--cui-page-layout-column-gap);
    padding-inline: var(--cui-page-layout-padding-inline);
    padding-block: var(--cui-page-layout-padding-block);
  }

  /* A flow or sticky header owns the leading space, so header-gap stays the only gap above the body.
     A floating header is zero-height and overlays the body, so the body keeps its own lead. */
  :where(
    [data-control-family="page-layout"][data-slot="header"]:not([data-variant="floating"])
      + [data-control-family="page-layout"][data-slot="body"]
  ) {
    padding-block-start: 0;
  }

  :where([data-control-family="page-layout"][data-slot="title"]) {
    grid-area: title;
    font-size: var(--text-heading-1);
    line-height: var(--text-heading-1--line-height);
    font-weight: var(--text-heading-1--font-weight);
    letter-spacing: var(--text-heading-1--letter-spacing);
    color: var(--foreground);
  }

  :where([data-control-family="page-layout"][data-slot="description"]) {
    grid-area: description;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="page-layout"][data-slot="actions"]) {
    grid-area: actions;
    justify-self: start;
  }

  @media (width >= 40rem) {
    :where([data-control-family="page-layout"][data-slot="header"]) {
      grid-template-columns: minmax(0, 1fr) auto;
      grid-template-areas: "title actions" "description actions";
    }

    :where([data-control-family="page-layout"][data-slot="actions"]) {
      justify-self: end;
    }
  }

  :where([data-control-family="page-layout"][data-slot="header"][data-variant="sticky"]) {
    position: sticky;
    top: var(--cui-page-layout-sticky-gap);
    z-index: 20;
  }

  /* Zero height: the band hangs over the body instead of displacing it. */
  :where([data-control-family="page-layout"][data-slot="header"][data-variant="floating"]) {
    position: sticky;
    top: var(--cui-page-layout-sticky-gap);
    z-index: 20;
    align-items: start;
    height: 0;
    padding-block: 0;
    pointer-events: none;
  }

  :where([data-control-family="page-layout"][data-slot="header"][data-variant="floating"] > *) {
    pointer-events: auto;
  }

  :where(
    [data-control-family="page-layout"][data-slot="header"][data-variant="floating"]
      [data-control-family="page-layout"][data-slot="actions"]
  ) {
    justify-self: end;
  }

  :where([data-control-family="page-layout"][data-slot="root"][data-width="full"] [data-control-family="page-layout"][data-slot="body"]) {
    padding-block: 0;
    padding-inline: 0;
  }

  :where([data-control-family="page-layout"][data-slot="aside"]) {
    display: none;
  }

  @media (width >= 80rem) {
    :where([data-control-family="page-layout"][data-slot="body"][data-aside]),
    :where(
        [data-control-family="page-layout"][data-slot="header"]:has(+ [data-control-family="page-layout"][data-slot="body"][data-aside])
      ) {
      --cui-page-layout-size: calc(
        var(--cui-page-layout-article-size) +
        var(--cui-page-layout-column-gap) +
        var(--cui-page-layout-aside-size) +
        var(--cui-page-layout-padding-inline) *
        2
      );
    }

    :where([data-control-family="page-layout"][data-slot="body"][data-aside]) {
      grid-template-columns: minmax(0, var(--cui-page-layout-article-size)) var(--cui-page-layout-aside-size);
    }

    :where([data-control-family="page-layout"][data-slot="aside"]) {
      display: block;
    }
  }
}

@property --cui-page-layout-article-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-aside-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-padding-inline {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-padding-block {
  syntax: "*";
  inherits: true;
}

@property --cui-page-layout-column-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-header-start-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-header-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-header-column-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-header-row-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-page-layout-size {
  syntax: "*";
  inherits: true;
}

@property --cui-page-layout-sticky-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import type { PageLayoutKnobStyle } from "@/components/control-ui/knob-contracts/page-layout-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { useSkin } from "@/components/control-ui/skin-provider";
import { ScrollArea, type ScrollAreaProps } from "@/components/control-ui/ui/scroll-area";

export const pageWidths = ["prose", "content", "wide", "full"] as const;
export type PageWidth = (typeof pageWidths)[number];

export const pageScrollModes = ["page", "inset", "none"] as const;
export type PageScrollMode = (typeof pageScrollModes)[number];
export type PageScroll = PageScrollMode | "auto";

export const pageHeaderVariants = ["flow", "sticky", "floating"] as const;
export type PageHeaderVariant = (typeof pageHeaderVariants)[number];

type PageStyle = CSSProperties & PageLayoutKnobStyle;

export function usePageScroll(scroll: PageScroll = "auto"): PageScrollMode {
  const skin = useSkin();
  if (scroll !== "auto") return scroll;
  return skin.sidebarLayout === "page" ? "page" : "inset";
}

export type PageLayoutProps = Omit<ComponentProps<"div">, "style"> & {
  scroll?: PageScroll;
  width?: PageWidth;
  scrollViewportRef?: ScrollAreaProps["viewportRef"];
  style?: PageStyle;
};

export function PageLayout({ scroll = "auto", width = "prose", scrollViewportRef, children, className, ...props }: PageLayoutProps) {
  const resolvedScroll = usePageScroll(scroll);
  const scrollsInset = resolvedScroll === "inset";

  return (
    <div
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="root"
      data-scroll={resolvedScroll}
      data-width={width}
      className={cn("flex w-full flex-col", resolvedScroll !== "page" && "min-h-0 flex-1 overflow-hidden", className)}
      {...props}
    >
      {scrollsInset ? (
        <ScrollArea
          className="min-h-0 flex-1"
          viewportClassName="scroll-smooth motion-reduce:scroll-auto"
          viewportRef={scrollViewportRef}
          lockAxis="x"
        >
          {children}
        </ScrollArea>
      ) : (
        children
      )}
    </div>
  );
}

export type PageHeaderProps = Omit<ComponentProps<"header">, "style"> & {
  variant?: PageHeaderVariant;
  style?: PageStyle;
};

export function PageHeader({ variant = "flow", className, ...props }: PageHeaderProps) {
  return (
    <header
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="header"
      data-variant={variant}
      className={className}
      {...props}
    />
  );
}

export type PageTitleProps = Omit<ComponentProps<"h1">, "style"> & { style?: PageStyle };

export function PageTitle({ className, ...props }: PageTitleProps) {
  return (
    <h1
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="title"
      className={cn("text-balance", className)}
      {...props}
    />
  );
}

export type PageDescriptionProps = Omit<ComponentProps<"p">, "style"> & { style?: PageStyle };

export function PageDescription({ className, ...props }: PageDescriptionProps) {
  return (
    <p
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="description"
      className={cn("text-pretty", className)}
      {...props}
    />
  );
}

export type PageActionsProps = Omit<ComponentProps<"div">, "style"> & { style?: PageStyle };

export function PageActions({ className, ...props }: PageActionsProps) {
  return (
    <div
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="actions"
      className={cn("flex items-center gap-2", className)}
      {...props}
    />
  );
}

export type PageBodyProps = Omit<ComponentProps<"div">, "style"> & {
  aside?: ReactNode;
  contentClassName?: string;
  style?: PageStyle;
};

export function PageBody({ aside, contentClassName, children, className, ...props }: PageBodyProps) {
  return (
    <div
      data-control-ui="page-layout"
      data-control-family="page-layout"
      data-slot="body"
      data-aside={aside ? "" : undefined}
      className={className}
      {...props}
    >
      <div data-control-ui="page-layout" data-control-family="page-layout" data-slot="content" className={cn("min-w-0", contentClassName)}>
        {children}
      </div>
      {aside ? (
        <aside data-control-ui="page-layout" data-control-family="page-layout" data-slot="aside">
          {aside}
        </aside>
      ) : null}
    </div>
  );
}
